      + '<td class="rtl-num">' + _rtlBar(r.memPct, memC) + '</td>'
      + '<td class="rtl-num">' + _rtlBar(r.hddPct, hddC) + '</td>'
      + '<td class="rtl-num">' + (r.clients != null ? r.clients : dash) + '</td>'
